from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        pairs_at = [[] for _ in range(n + 1)]

        for i, (a, b) in enumerate(conflictingPairs):
            u, v = min(a, b), max(a, b)
            pairs_at[v].append((u, i))

        best = (0, -1)
        second_best = (0, -1)

        base = 0
        benefit = [0] * m

        for r in range(1, n + 1):
            for u, idx in pairs_at[r]:
                if u > best[0]:
                    second_best = best
                    best = (u, idx)
                elif u >= second_best[0]:
                    second_best = (u, idx)

            max_left, best_idx = best
            second_left = second_best[0]

            base += r - max_left

            if best_idx != -1:
                benefit[best_idx] += max_left - second_left

        return base + max(benefit)
